<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        if (!obj || typeof path !== 'string') return defaultValue;
        let keys = path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                 const actualValue = current[0];
                 return typeof actualValue === 'boolean' ? actualValue : String(actualValue);
            }
            return defaultValue;
        }
        return typeof current === 'boolean' ? current : String(current);
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        if (!valueMainDisplay) return;

        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;
        let descriptionText = "";

        const descriptionMatch = String(fullDisplayString).match(/\s*\((.+)\)$/);
        if (descriptionMatch && descriptionMatch[1]) {
            descriptionText = descriptionMatch[1];
            fullDisplayString = String(fullDisplayString).substring(0, descriptionMatch.index).trim();
        }

        if (valueDescDisplay) {
            valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";
        }

        const parts = String(fullDisplayString).split('->');
        const mainText = parts.length > 1 ? parts[1].trim() : parts[0].trim();
        valueMainDisplay.innerText = mainText;

        const valueMatch = mainText.match(/-?\d+(\.\d+)?/);
        if (valueMatch) {
            numericValue = parseFloat(valueMatch[0]);
        }

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if (color) progressBar.style.backgroundColor = color;
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                console.warn("Status Bar Info: Could not retrieve valid message data.");
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;

            if (!characterData) {
                console.error("Status Bar Error: 'display_data' or 'stat_data' not found in gameData.");
                return;
            }

            if (characterData.主角) {
                updateProgressBar('protagonist-fame-bar', 'protagonist-fame', 'protagonist-fame-desc', SafeGetValue(characterData, '主角.名声'), 0, 100, 'var(--color-accent-gold)');
                updateProgressBar('protagonist-skill-bar', 'protagonist-skill', 'protagonist-skill-desc', SafeGetValue(characterData, '主角.招式'), 0, 200, 'var(--color-accent-blue)');
                updateProgressBar('protagonist-mind-bar', 'protagonist-mind', 'protagonist-mind-desc', SafeGetValue(characterData, '主角.心识'), 0, 100, 'var(--color-accent-purple)');
                if (characterData.主角.内力) {
                    updateProgressBar('protagonist-bihuo-bar', 'protagonist-bihuo', 'protagonist-bihuo-desc', SafeGetValue(characterData, '主角.内力.碧火神功'), 0, 800, 'var(--color-accent-green)');
                }
            }

            if (characterData.好感度) {
                updateProgressBar('love-huanghou-bar', 'love-huanghou', 'love-huanghou-desc', SafeGetValue(characterData, '好感度.皇后'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-huangying-bar', 'love-huangying', 'love-huangying-desc', SafeGetValue(characterData, '好感度.黄缨'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-renyizi-bar', 'love-renyizi', 'love-renyizi-desc', SafeGetValue(characterData, '好感度.任宜紫'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-xuziyi-bar', 'love-xuziyi', 'love-xuziyi-desc', SafeGetValue(characterData, '好感度.许缁衣'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-shijier-bar', 'love-shijier', 'love-shijier-desc', SafeGetValue(characterData, '好感度.时霁儿'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-shaoqianqian-bar', 'love-shaoqianqian', 'love-shaoqianqian-desc', SafeGetValue(characterData, '好感度.邵芊芊'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-leimingyao-bar', 'love-leimingyao', 'love-leimingyao-desc', SafeGetValue(characterData, '好感度.雷冥杳'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-shuyujie-bar', 'love-shuyujie', 'love-shuyujie-desc', SafeGetValue(characterData, '好感度.漱玉节'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-hejunpan-bar', 'love-hejunpan', 'love-hejunpan-desc', SafeGetValue(characterData, '好感度.何君盼'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-macanniang-bar', 'love-macanniang', 'love-macanniang-desc', SafeGetValue(characterData, '好感度.马蚕娘'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-ranhongxia-bar', 'love-ranhongxia', 'love-ranhongxia-desc', SafeGetValue(characterData, '好感度.染红霞'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-hengshuying-bar', 'love-hengshuying', 'love-hengshuying-desc', SafeGetValue(characterData, '好感度.横疏影'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-fuchijin-bar', 'love-fuchijin', 'love-fuchijin-desc', SafeGetValue(characterData, '好感度.符赤锦'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-xueyanqing-bar', 'love-xueyanqing', 'love-xueyanqing-desc', SafeGetValue(characterData, '好感度.雪艳青'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-xianzi-bar', 'love-xianzi', 'love-xianzi-desc', SafeGetValue(characterData, '好感度.弦子'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-shensuyun-bar', 'love-shensuyun', 'love-shensuyun-desc', SafeGetValue(characterData, '好感度.沈素云'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-meier-bar', 'love-meier', 'love-meier-desc', SafeGetValue(characterData, '好感度.媚儿'), 0, 100, 'var(--color-accent-red)');
                updateProgressBar('love-mingzhanxue-bar', 'love-mingzhanxue', 'love-mingzhanxue-desc', SafeGetValue(characterData, '好感度.明栈雪'), 0, 100, 'var(--color-accent-red)');
            }

            if (characterData.关系) {
                updateProgressBar('relation-brlyc-bar', 'relation-brlyc', 'relation-brlyc-desc', SafeGetValue(characterData, '关系.白日流影城'), -50, 50, 'var(--color-accent-blue)');
                updateProgressBar('relation-qfz-bar', 'relation-qfz', 'relation-qfz-desc', SafeGetValue(characterData, '关系.青锋照'), -50, 50, 'var(--color-accent-blue)');
                updateProgressBar('relation-sytx-bar', 'relation-sytx', 'relation-sytx-desc', SafeGetValue(characterData, '关系.水月停轩'), -50, 50, 'var(--color-accent-blue)');
                updateProgressBar('relation-tlx-bar', 'relation-tlx', 'relation-tlx-desc', SafeGetValue(characterData, '关系.天罗香'), -50, 50, 'var(--color-accent-blue)');
                updateProgressBar('relation-wudi-bar', 'relation-wudi', 'relation-wudi-desc', SafeGetValue(characterData, '关系.五帝窟'), -50, 50, 'var(--color-accent-blue)');
                updateProgressBar('relation-ysm-bar', 'relation-ysm', 'relation-ysm-desc', SafeGetValue(characterData, '关系.游尸门'), -50, 50, 'var(--color-accent-blue)');
                updateProgressBar('relation-zdjjf-bar', 'relation-zdjjf', 'relation-zdjjf-desc', SafeGetValue(characterData, '关系.镇东将军府'), -50, 50, 'var(--color-accent-blue)');
            }

            if (characterData.欣赏值) {
