                updateProgressBar('admire-huyanzhi-bar', 'admire-huyanzhi', 'admire-huyanzhi-desc', SafeGetValue(characterData, '欣赏值.胡彦之'), 0, 50, 'var(--color-accent-purple)');
            }

            if (characterData.状态) {
                const updateFlag = (id, path) => {
                    const el = document.getElementById(id);
                    if (!el) return;

                    const rawValue = SafeGetValue(characterData, path, '0');
                    let finalValue = '0';

                    const match = String(rawValue).match(/-?\d+(\.\d+)?(?!.*\d)/);
                    if (match) {
                        finalValue = match[0];
                    }

                    const isTriggered = finalValue == 1;
                    el.innerText = isTriggered ? '已达成' : '未达成';
                    el.className = isTriggered ? 'value-main triggered' : 'value-main not-triggered';
                };

                updateFlag('flag-arrived-zhuchengshan', '状态.是否到达过朱城山');
                updateFlag('flag-arrived-lianjuesi', '状态.是否到达过莲觉寺');
                updateFlag('flag-arrived-yuechengpu', '状态.是否到达过越城浦');

                updateFlag('flag-overheard-jiedao', '状态.是否偷听过聂冥途与阴宿冥密谈');
