                updateFlag('flag-event-brlyc', '状态.是否已触发白日流影城特殊事件');
                updateFlag('flag-got-cangfengdao', '状态.是否已获得藏锋刀');
                updateFlag('flag-passed-ysm-test', '状态.是否已通过游尸门考验');
                updateFlag('flag-conquered-meier', '状态.是否已征服媚儿');
                updateFlag('flag-knows-hsy-secret', '状态.是否已获知横疏影身世');
                updateFlag('flag-saved-by-mcn', '状态.是否已触发马蚕娘救场');

                updateFlag('flag-learned-duoshe', '状态.是否学习过夺舍大法');
                updateFlag('flag-mastered-jimiedao', '状态.是否已完全领悟寂灭刀');
                updateFlag('flag-learned-biliguishou', '状态.是否已习得薜荔鬼手');
                updateFlag('flag-learned-tianfu', '状态.是否已习得天覆神功');
                updateFlag('flag-learned-xuanxiao', '状态.是否已习得玄嚣八阵字');
                updateFlag('flag-learned-sijian', '状态.是否已习得思见身中');
                updateFlag('flag-learned-bihuo', '状态.是否已习得碧火神功');
            }

        } catch (error) {
            const card = document.getElementById('status-card');
            if (card) card.innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
